import os
from typing import Optional

from google.cloud import pubsub_v1
from google.api_core.exceptions import GoogleAPICallError


class DeadLetterPublisher:
    def __init__(
        self,
        project_id: Optional[str] = None,
        dead_letter_topic: Optional[str] = None,
    ) -> None:
        self.project_id = project_id or os.environ["GOOGLE_CLOUD_PROJECT"]
        self.dead_letter_topic = dead_letter_topic or os.environ["DEAD_LETTER_TOPIC"]
        self.publisher = pubsub_v1.PublisherClient()
        self.topic_path = self.publisher.topic_path(self.project_id, self.dead_letter_topic)

    def send_failed_message(
        self,
        message: bytes,
        original_topic: Optional[str] = None,
        error_reason: Optional[str] = None,
        subscription: Optional[str] = None,
        message_id: Optional[str] = None,
    ) -> str:
        attributes = {}
        if original_topic:
            attributes["original_topic"] = original_topic
        if error_reason:
            attributes["error_reason"] = error_reason
        if subscription:
            attributes["subscription"] = subscription
        if message_id:
            attributes["message_id"] = message_id

        future = self.publisher.publish(self.topic_path, message, **attributes)
        return future.result()

    def send_failed_message_text(
        self,
        message_text: str,
        original_topic: Optional[str] = None,
        error_reason: Optional[str] = None,
        subscription: Optional[str] = None,
        message_id: Optional[str] = None,
    ) -> str:
        return self.send_failed_message(
            message_text.encode("utf-8"),
            original_topic=original_topic,
            error_reason=error_reason,
            subscription=subscription,
            message_id=message_id,
        )


def send_failed_message_to_dead_letter(
    message: bytes,
    project_id: Optional[str] = None,
    dead_letter_topic: Optional[str] = None,
    original_topic: Optional[str] = None,
    error_reason: Optional[str] = None,
    subscription: Optional[str] = None,
    message_id: Optional[str] = None,
) -> str:
    publisher = DeadLetterPublisher(project_id=project_id, dead_letter_topic=dead_letter_topic)
    try:
        return publisher.send_failed_message(
            message,
            original_topic=original_topic,
            error_reason=error_reason,
            subscription=subscription,
            message_id=message_id,
        )
    except GoogleAPICallError:
        raise


def send_failed_text_to_dead_letter(
    message_text: str,
    project_id: Optional[str] = None,
    dead_letter_topic: Optional[str] = None,
    original_topic: Optional[str] = None,
    error_reason: Optional[str] = None,
    subscription: Optional[str] = None,
    message_id: Optional[str] = None,
) -> str:
    publisher = DeadLetterPublisher(project_id=project_id, dead_letter_topic=dead_letter_topic)
    try:
        return publisher.send_failed_message_text(
            message_text,
            original_topic=original_topic,
            error_reason=error_reason,
            subscription=subscription,
            message_id=message_id,
        )
    except GoogleAPICallError:
        raise
